	std::string hudsonLogo(ColorDepth depth)
	{
		if (depth == ColorDepth::TrueColor) return join(HUDSON_TRUECOLOR, HUDSON_TRUECOLOR_ROWS);
		if (depth == ColorDepth::Ansi256) return join(HUDSON_ANSI256, HUDSON_ANSI256_ROWS);
		return join(HUDSON_PLAIN, HUDSON_PLAIN_ROWS);
	}

	std::string warpedLogo(ColorDepth depth)
	{
		if (depth == ColorDepth::TrueColor) return join(WARPED_TRUECOLOR, WARPED_TRUECOLOR_ROWS);
		if (depth == ColorDepth::Ansi256) return join(WARPED_ANSI256, WARPED_ANSI256_ROWS);
		return join(WARPED_PLAIN, WARPED_PLAIN_ROWS);
	}

	std::string tividyLogo(ColorDepth depth)
	{
		if (depth == ColorDepth::TrueColor) return join(TIVIDY_TRUECOLOR, TIVIDY_TRUECOLOR_ROWS);
		if (depth == ColorDepth::Ansi256) return join(TIVIDY_ANSI256, TIVIDY_ANSI256_ROWS);
		return join(TIVIDY_PLAIN, TIVIDY_PLAIN_ROWS);
	}
